package com.greatleyposhley.professy.collaboration;
import com.greatleyposhley.professy.controllers.BoardFilterController;import com.greatleyposhley.professy.entities.*;import com.greatleyposhley.professy.repositories.*;import com.greatleyposhley.professy.services.BoardService;import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.server.ResponseStatusException;import java.util.*;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
class BoardCreationTest {
 private WorkAccess access(JdbcTemplate jdbc){var a=spy(new WorkAccess(mock(UserAccountRepository.class),jdbc,mock(WorkspacePolicy.class)));var u=new UserAccount();u.setId(3L);u.setOrgId(7L);doReturn(u).when(a).actor();doNothing().when(a).project(anyLong());doNothing().when(a).require(anyString());return a;}
 @Test void replacingFiltersUsesBoardPermissionAndOneValidatedBoard(){var jdbc=mock(JdbcTemplate.class);var access=access(jdbc);var repository=mock(BoardFilterRepository.class);when(jdbc.queryForList(anyString(),eq(Long.class),any(Object[].class))).thenReturn(List.of(9L));var filter=new BoardFilter();filter.setBoardId(123L);filter.setFilterType("SPRINT");filter.setFilterValue("12");new BoardFilterController(repository,access).replace(5L,List.of(filter));verify(access).require("BOARDS.UPDATE");verify(access).project(9L);assertEquals(5L,filter.getBoardId());var order=inOrder(repository);order.verify(repository).deleteByBoardId(5L);order.verify(repository).flush();order.verify(repository).saveAll(List.of(filter));}
 @Test void boardInAnotherOrganizationCannotHaveItsFiltersChanged(){var jdbc=mock(JdbcTemplate.class);var access=access(jdbc);var repository=mock(BoardFilterRepository.class);when(jdbc.queryForList(anyString(),eq(Long.class),any(Object[].class))).thenReturn(List.of());assertThrows(ResponseStatusException.class,()->new BoardFilterController(repository,access).replace(5L,List.of()));verifyNoInteractions(repository);}
 @Test void boardDetailsRemainOrganizationScoped(){var repository=mock(BoardRepository.class);var board=new Board();board.setOrgId(8L);when(repository.findById(5L)).thenReturn(Optional.of(board));assertThrows(RuntimeException.class,()->new BoardService(repository).getBoardById(7L,5L));}
}
